intentos.respuesta_cruda:
{
  "sql": "SELECT rango_retraso, pedidos, ROUND(100.0 * SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) / pedidos, 2) AS pct_2_o_menos, ROUND(100.0 * SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) / vw_retraso_por_rango.pedidos, 2) AS pct_2_o_menos_a_tiempo FROM vw_retraso_por_rango WHERE rango_retraso IN ('a_tiempo', '1-3', '4-7', '8-14') GROUP BY rango_retraso HAVING pct_2_o_menos >= 2 * pct_2_o_menos_a_tiempo ORDER BY pct_2_o_menos DESC LIMIT 1"
}
